head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst70000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#searchForm").find("input:checkbox[name=listTypeArr]").click(async function() {
                await scwin.fnCheckListType();
        });
        $("#chk_5_0").bind("click", function() {
                const $al = $("input:checkbox[name=secuGrpArr]");
                if ($("#chk_5_0").prop("checked")) {
                    $al.prop("checked", true);
                } else {
                    $al.prop("checked", false);
                }
        });
        $("#chk_5_1").bind("click", function() {
                if ($("#chk_5_1").prop("checked")) {
                    if ($("#chk_5_2").prop("checked") && $("#chk_5_3").prop("checked")) {
                        (($c.util.getComponent('chk_5_0')) && ($c.util.getComponent('chk_5_0')).setValue ? ($c.util.getComponent('chk_5_0')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                    }
                } else {
                    (($c.util.getComponent('chk_5_0')) && ($c.util.getComponent('chk_5_0')).setValue ? ($c.util.getComponent('chk_5_0')).setValue((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
                }
        });
        $("#chk_5_2").bind("click", function() {
                if ($("#chk_5_2").prop("checked")) {
                    if ($("#chk_5_1").prop("checked") && $("#chk_5_3").prop("checked")) {
                        (($c.util.getComponent('chk_5_0')) && ($c.util.getComponent('chk_5_0')).setValue ? ($c.util.getComponent('chk_5_0')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                    }
                } else {
                    (($c.util.getComponent('chk_5_0')) && ($c.util.getComponent('chk_5_0')).setValue ? ($c.util.getComponent('chk_5_0')).setValue((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
                }
        });
        $("#chk_5_3").bind("click", function() {
                if ($("#chk_5_3").prop("checked")) {
                    if ($("#chk_5_2").prop("checked") && $("#chk_5_1").prop("checked")) {
                        (($c.util.getComponent('chk_5_0')) && ($c.util.getComponent('chk_5_0')).setValue ? ($c.util.getComponent('chk_5_0')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                    }
                } else {
                    (($c.util.getComponent('chk_5_0')) && ($c.util.getComponent('chk_5_0')).setValue ? ($c.util.getComponent('chk_5_0')).setValue((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
                }
        });
        await scwin.fnInit();
        $(".ord-07").attr("onclick", "fnSetSearchDate5('2000-01-01', '1'); fnSwapSearchBtnDates('7'); return false;");
        $("#cal_fromDate").change(function() {
                chkPeriod2Mil($(this).val());
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst70000.onpageload' });
    }
};

