 * @hidden N
 */
scwin.btn_fnMenuSetting_onclick = function(e){
    try {
        scwin.fnMenuSetting(true); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst70000.btn_fnMenuSetting_onclick' }); }
};

/**
 * @method
 * @name btn_fnFindCorpName2_onclick
 * @description btn_fnFindCorpName2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCorpName2_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst70000.btn_fnFindCorpName2_onclick' }); }
};

/**
 * @method
 * @name cal_fromDate_onchange
 * @description 「상장일 기간 선택 첫번째」 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.cal_fromDate_onchange = function(e){
    try {
        scwin.fnChkLmtDate();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst70000.cal_fromDate_onchange' }); }
};scwin.ipt_chAll1_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.changeAllCheckState()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst70000.ipt_chAll1_onclick' }); }
};

/**
