        chkLmnts[i].checked = true;
    }
};

/**
 * @method
 * @name fnCheckListType
 * @description fn Check List Type 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCheckListType = async function () {
    const chkLmnts = document.getElementsByName("listTypeArr");
    let chkCnt = 0;
    let check_setting = "";
    for (let i = 0; i < chkLmnts.length; i++) {
        if (chkLmnts[i].checked === true) {
            check_setting += chkLmnts[i].value + "|";
            chkCnt++;
        }
    }
    if (chkCnt === 0) {
        await $c.win.alert('상장유형을 하나 이상 선택해주세요.');
        return false;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("listTypeArrStr", check_setting);
    return true;
};

