        await $c.win.alert("조회한 회사명이 존재하지 않습니다. \n정확한 회사명을 입력해 주세요. \n회사명이 정확하지 않으시면 회사명 검색을 이용해주세요.");
    } else {
        await scwin.fnSearchInit();
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    if (ipt_repIsuSrtCd === "") {
        ipt_repIsuSrtCd = isurCd;
    }
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
};

/**
 * @method
 * @name changeAllCheckState
 * @description change All Check State 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeAllCheckState = function () {
    const length = $("#searchForm").find('input:checkbox[name=choicTypeArr]').length;
    for (let i = 0; i < length; i++) {
        if ($("#ipt_chAll1").is(":checked")) {
            $("#chk" + i).attr("checked", true);
        } else {
            $("#chk" + i).attr("checked", false);
        }
    }
};
